const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function boil(pot, ms) {
  await delay(ms);
  console.log(pot + " boiled");
}

async function cook() {
  for (const [pot, ms] of [["rice", 40], ["pasta", 10], ["eggs", 20]]) {
    await boil(pot, ms);
  }
  console.log("dinner");
}

cook();
console.log("cooking");
